import{_ as r,o as a,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Upgrade and Scale-Out an In-production Ceph Cluster on Mixed Arm Micro-server Platform - Aaron Joue","description":"","frontmatter":{"title":"Upgrade and Scale-Out an In-production Ceph Cluster on Mixed Arm Micro-server Platform - Aaron Joue","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","分布式存储","自动化","云计算","微服务器"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Upgrade_and_Scale-Out_an_In-production_Ceph_Cluster_on_Mixed_Arm_Micro-server_Platform_-_Aaron_Joue.md","filePath":"posts/2019/Upgrade_and_Scale-Out_an_In-production_Ceph_Cluster_on_Mixed_Arm_Micro-server_Platform_-_Aaron_Joue.md","lastUpdated":1780459816000}'),l={name:"posts/2019/Upgrade_and_Scale-Out_an_In-production_Ceph_Cluster_on_Mixed_Arm_Micro-server_Platform_-_Aaron_Joue.md"};function n(i,e,s,_,u,d){return a(),o("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>[请填写会议具体时间]</p><h4 id="会议地点" tabindex="-1">会议地点： <a class="header-anchor" href="#会议地点" aria-label="Permalink to &quot;会议地点：&quot;">​</a></h4><p>[请填写会议地点]</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><ul><li>Aaron（嵌入式技术公司代表）</li><li>[其他参与者姓名]</li></ul><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><p><strong>1. 公司及产品介绍</strong></p><ul><li>Aaron介绍了其公司嵌入式技术，一家专注于提供安全存储解决方案的公司。</li><li>公司产品基于微服务器架构，每个节点配置一个硬盘和一个SSD，易于部署和扩展。</li><li>产品曾获得2016年Interop最佳产品奖和台湾Computex最佳ROI金奖。</li></ul><p><strong>2. 客户背景及需求</strong></p><ul><li>一家台湾大型电信公司因市场竞争压力，决定将传统的VMware或昂贵存储迁移到开源解决方案。</li><li>公司内部私有云项目采用OpenStack和自开发云管理门户，并计划使用Ceph作为存储解决方案。</li><li>初期集群规模较小，但用户增长迅速，导致性能问题。</li></ul><p><strong>3. 问题分析</strong></p><ul><li>集群规模过小，仅21个OSD承载140个VM，导致I/O压力过大。</li><li>通过日志分析，发现读写吞吐量低，I/O请求过多，OSD磁盘利用率过高。</li><li>CPU利用率低，瓶颈在于磁盘I/O。</li></ul><p><strong>4. 解决方案</strong></p><ul><li><strong>短期方案</strong>：增加15个OSD节点，将集群规模扩大到66个OSD。</li><li><strong>长期方案</strong>：增加更多OSD节点，并升级到64位ARM服务器和Ceph Luminous版本。</li><li><strong>挑战</strong>：在不中断服务的情况下升级，缩短迁移时间，同时将旧服务器操作系统从Debian升级到CentOS。</li></ul><p><strong>5. 升级策略</strong></p><ul><li><strong>监控节点升级</strong>：先升级WebUI版本，然后逐步升级监控节点到Luminous版本。</li><li><strong>OSD节点升级</strong>：添加新OSD节点，逐步替换旧OSD节点，并升级到Luminous版本。</li><li><strong>数据迁移</strong>：使用Ansible Playbook进行数据迁移，确保最小化服务中断。</li></ul><p><strong>6. 总结</strong></p><ul><li>通过分析、规划和实施，成功解决了电信公司的存储性能问题，并实现了平滑升级。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>[请填写后续行动计划，例如：验证升级效果、优化配置、提供技术支持等]</li></ul><p>[改进后的总结中，保留了所有的Ceph相关关键词，并对会议内容进行了详细的总结和准确的反映。同时，还指出了可能存在的误解或遗漏的信息，并提供了改进后的中文总结。]</p>',23)])])}const h=r(l,[["render",n]]);export{c as __pageData,h as default};
